<script setup lang="ts">
import {ref,computed,onUnmounted,watch} from 'vue'
import {Landmark,CloudUpload,ShieldCheck,Wallet,Users,Play,Pause,RotateCcw,Check,AlertTriangle,ArrowRight} from 'lucide-vue-next'
const emit=defineEmits<{passport:[]}>()
const props=defineProps<{compact?:boolean}>()
const scenario=ref('success'),step=ref(-1),running=ref(false)
let timer:ReturnType<typeof setInterval>|undefined
const steps=[{label:'Mas’ul idora',detail:'Ijro xabarini yuboradi',icon:Landmark},{label:'Integratsiya',detail:'Format va chora kodi',icon:CloudUpload},{label:'Yagona hisob',detail:'Shaxs, davr, takror',icon:ShieldCheck},{label:'To‘lov / xizmat',detail:'Natija qayd etiladi',icon:Wallet},{label:'Fuqaro kabineti',detail:'Oila tarixida aks etadi',icon:Users}]
const stopAt=computed(()=>scenario.value==='invalid'?1:scenario.value==='duplicate'?2:4)
const done=computed(()=>step.value===stopAt.value)
const blocked=computed(()=>done.value&&scenario.value!=='success')
const descriptions=computed(()=>['Manba identifikatori bilan ijro xabari olindi.',scenario.value==='invalid'?'Chora kodi yo‘q. Xabar tuzatish uchun idoraga qaytarildi.':'Majburiy maydonlar va chora kodi tasdiqlandi.',scenario.value==='duplicate'?'Bu hodisa avval qayd etilgan. Yangi hisob yozuvi yaratilmadi.':'Takrorlanish aniqlanmadi. Yagona hisob yozuvi yaratildi.','Ko‘rsatilgan yordam yoki xizmat natijasi hisobga olindi.','Ijro fuqaro va oila tarixida ko‘rinadi.'])
function pause(){clearInterval(timer);timer=undefined;running.value=false}
function next(){if(done.value)return;step.value++;if(done.value)pause()}
function play(){if(running.value){pause();return}if(done.value)step.value=-1;running.value=true;next();if(!done.value)timer=setInterval(next,1500)}
function reset(){pause();step.value=-1}
watch(scenario,reset)
onUnmounted(pause)
</script>
<template><section class="execution" :class="{compact:props.compact}"><div class="execution-head"><div><span class="flow-eyebrow">TIZIM QANDAY ISHLAYDI</span><h3>Idoradan fuqaro kabinetigacha</h3></div><span class="flow-state" :class="{success:done&&!blocked,danger:blocked}"><i></i>{{ blocked?'Tekshiruvda to‘xtatildi':done?'Muvaffaqiyatli yakunlandi':running?'Xabar qayta ishlanmoqda':'Namunaviy ijro oqimi' }}</span></div><div class="flow-controls"><div class="scenario-tabs" aria-label="Xabar ssenariysi"><button v-for="[key,title] in [['success','To‘g‘ri xabar'],['duplicate','Takroriy xabar'],['invalid','Chora kodisiz']]" :key="key" :aria-pressed="scenario===key" @click="scenario=key!">{{ title }}</button></div><button class="flow-play" @click="play"><component :is="running?Pause:done?RotateCcw:Play" :size="15"/>{{ running?'Pauza':done?'Qayta ko‘rsatish':'Oqimni boshlash' }}</button><button v-if="!compact" class="flow-step" :disabled="done" @click="pause();next()">Bir qadam <ArrowRight :size="14"/></button></div><div class="flow-track"><article v-for="(item,i) in steps" :key="item.label" :class="{passed:step>i||(done&&!blocked&&step===i),active:step===i&&!done,blocked:blocked&&step===i}"><div class="flow-icon"><component :is="blocked&&step===i?AlertTriangle:step>i||(done&&!blocked&&step===i)?Check:item.icon" :size="22"/></div><strong>{{ item.label }}</strong><span>{{ item.detail }}</span><div v-if="i<4" class="flow-wire"><i v-if="running&&step===i"></i></div></article></div><div class="flow-result" aria-live="polite"><span :class="{danger:blocked,success:done&&!blocked}">{{ step<0?'Ssenariyni tanlang va xabarning yo‘lini kuzating.':descriptions[step] }}</span><button v-if="done&&!blocked" @click="emit('passport')">Fuqaro pasportini ochish <ArrowRight :size="14"/></button></div><template v-if="!compact"><div class="flow-counts"><div><span>Kiruvchi xabar</span><b>{{ step>=0?1:0 }}</b></div><div><span>Yangi hisob yozuvi</span><b class="success">{{ step>=2&&!blocked?1:0 }}</b></div><div><span>Tekshiruvda to‘xtatilgan</span><b class="danger">{{ blocked?1:0 }}</b></div><div><span>Kabinetda aks etgan</span><b class="success">{{ done&&!blocked?1:0 }}</b></div></div><div class="flow-journal"><h4>Qayta ishlash jurnali <small>DEMO-EVENT-001</small></h4><p v-if="step<0">Hozircha xabar yuborilmadi.</p><TransitionGroup name="event" tag="ol"><li v-for="(description,i) in descriptions.slice(0,step+1)" :key="description"><span>{{ String(i+1).padStart(2,'0') }}</span><b>{{ steps[i]?.label }}</b><p>{{ description }}</p><component :is="blocked&&step===i?AlertTriangle:Check" :size="16" :class="blocked&&step===i?'danger':'success'"/></li></TransitionGroup></div><p class="flow-note">Namoyish ssenariysi. Haqiqiy to‘lov, tayinlash yoki manba ma’lumotlariga o‘zgartirish kiritilmaydi.</p></template></section></template>
<style scoped>
.execution{border:1px solid var(--border);background:var(--card);border-radius:14px;padding:22px;color:var(--foreground)}.execution-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.flow-eyebrow{font-size:11px;font-weight:750;letter-spacing:.14em;color:var(--muted-foreground)}.execution h3{font-size:16px;font-weight:750;margin-top:5px}.flow-state{display:flex;gap:7px;align-items:center;background:var(--muted);border-radius:20px;padding:6px 10px;font-size:11px;color:#687c96}.flow-state i{width:6px;height:6px;background:currentColor;border-radius:50%}.flow-controls{display:flex;gap:9px;align-items:center;margin-top:20px}.scenario-tabs{display:flex;background:var(--muted);border:1px solid var(--border);border-radius:7px;padding:3px;gap:3px}.scenario-tabs button{font-size:11px;padding:6px 10px;color:var(--muted-foreground);border-radius:5px}.scenario-tabs button[aria-pressed=true]{background:var(--card);color:var(--primary);box-shadow:0 1px 4px #1d335215}.flow-play{margin-left:auto;background:var(--primary);color:white;display:flex;gap:7px;align-items:center;font-size:11px;font-weight:650;border-radius:7px;padding:9px 13px}.flow-step{display:flex;align-items:center;gap:6px;font-size:11px;border:1px solid var(--border);padding:8px;border-radius:7px}.flow-step:disabled{opacity:.4}.flow-track{display:grid;grid-template-columns:repeat(5,1fr);gap:15px;margin:28px 0 22px}.flow-track article{position:relative;display:flex;align-items:center;flex-direction:column;text-align:center;gap:7px}.flow-icon{height:48px;width:48px;display:grid;place-items:center;border:1px solid #dfe6f2;border-radius:13px;background:#f3f6fc;color:var(--muted-foreground);position:relative;z-index:1;transition:all .4s}.flow-track strong{font-size:11px;font-weight:700}.flow-track article>span{font-size:11px;color:var(--muted-foreground)}.flow-wire{height:2px;background:#e6ebf4;position:absolute;left:calc(50% + 24px);right:calc(-50% + 9px);top:24px;transition:background .4s}.flow-wire i{position:absolute;width:16px;height:6px;top:-2px;background:#4b83f5;border-radius:9px;animation:transmit 1.2s linear infinite}.active .flow-icon{background:#eaf1ff;border-color:#6490ef;color:var(--primary);box-shadow:0 0 0 6px color-mix(in srgb,var(--primary) 4%,transparent);animation:halo 1.3s infinite}.passed .flow-icon{background:#e9f8f3;color:#0c9977;border-color:#a9ddcc}.passed .flow-wire{background:#57bda2}.blocked .flow-icon{background:#fff1ee;border-color:#ecaa9b;color:#d86449}.flow-result{display:flex;justify-content:space-between;align-items:center;gap:12px;min-height:38px;border-top:1px dashed var(--border);padding-top:13px;font-size:11px;color:var(--muted-foreground)}.flow-result button{display:flex;gap:6px;align-items:center;color:var(--primary);font-weight:600}.flow-counts{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:24px 0}.flow-counts>div{border:1px solid var(--border);border-radius:10px;padding:16px;display:grid;gap:8px}.flow-counts span{font-size:11px;color:var(--muted-foreground)}.flow-counts b{font-size:27px}.success{color:#11977a!important}.danger{color:#d5664b!important}.flow-journal{border:1px solid var(--border);border-radius:10px;padding:18px}.flow-journal h4{font-size:13px;font-weight:700;display:flex;justify-content:space-between}.flow-journal small{font-size:11px;color:var(--muted-foreground)}.flow-journal li{display:flex;gap:12px;align-items:center;padding:12px 0;border-top:1px solid var(--border);font-size:11px}.flow-journal ol{margin-top:12px}.flow-journal li p{flex:1;color:var(--muted-foreground)}.flow-journal li>span{color:var(--muted-foreground)}.flow-note{font-size:11px;color:var(--muted-foreground);margin-top:12px}.event-enter-active{transition:all .4s}.event-enter-from{opacity:0;transform:translateX(-16px)}@keyframes transmit{from{left:0;opacity:0}30%{opacity:1}to{left:100%;opacity:0}}@keyframes halo{50%{box-shadow:0 0 0 9px color-mix(in srgb,var(--primary) 8%,transparent)}}@media(max-width:700px){.execution-head,.flow-controls{flex-wrap:wrap}.flow-track{gap:3px}.flow-track article>span{display:none}.flow-track strong{font-size:11px}.flow-counts{grid-template-columns:1fr 1fr}.flow-play{margin-left:0}.flow-journal li{flex-wrap:wrap}.scenario-tabs button{padding:5px}.execution{padding:14px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
